WITH segment_transactions AS (SELECT transactionid, amount, segment, currency FROM transactions_1k JOIN customers ON transactions_1k.customerid = customers.customerid) SELECT segment_transactions.segment, segment_transactions.currency, COUNT(*) as transaction_count, SUM(amount) as total_value, AVG(amount) as avg_value FROM segment_transactions GROUP BY segment_transactions.segment, segment_transactions.currency ORDER BY total_value DESC;
